<?php
require __DIR__ . '/includes/module.php';
$user = require_auth(); require_permission('products.view'); module_action('products');
$query = trim((string)($_GET['q'] ?? ''));
$sql = 'SELECT * FROM products WHERE business_id=? AND active=1'; $params = [(int)$user['business_id']];
if ($query !== '') { $sql .= ' AND (name LIKE ? OR sku LIKE ? OR hsn_sac LIKE ? OR category LIKE ?)'; array_push($params, ...array_fill(0,4,'%'.$query.'%')); }
$sql .= ' ORDER BY name'; $statement = db()->prepare($sql); $statement->execute($params); $rows = $statement->fetchAll();
$fields = '<label>Name *<input required name="name"></label><label>SKU / code<input name="sku"></label><label>HSN / SAC<input name="hsn_sac" maxlength="20"></label><label>Type<select name="kind"><option>Service</option><option>Product</option></select></label><label>Category<input name="category"></label><label>Unit<input name="unit" value="unit"></label><label>Price<input name="price" type="number" min="0" step="0.01" value="0"></label><label>Configured GST rate %<input name="tax_rate" type="number" min="0" max="100" step="0.001" value="0"></label>';
page_start('Products & services','products'); module_css('products');
?><div class="section-head"><div><span class="eyebrow">CATALOG</span><h1>Products & services</h1><p>Set item prices, HSN/SAC codes and configured tax rates.</p></div><button class="button primary" onclick="document.getElementById('record-modal').showModal()"><i class="ti ti-plus"></i> Add item</button></div>
<div class="content-card"><form class="toolbar"><input class="search" name="q" value="<?=e($query)?>" placeholder="Search items or code"><button class="button secondary">Search</button><span class="help-text"><?=count($rows)?> active items</span></form><div class="table-scroll"><table class="data-table"><thead><tr><th>ITEM</th><th>TYPE</th><th>SKU</th><th>HSN / SAC</th><th>CATEGORY</th><th>UNIT</th><th>PRICE</th><th>GST RATE</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td class="table-strong"><?=e($row['name'])?></td><td><span class="pill"><?=e($row['kind'])?></span></td><td><?=e($row['sku']?:'—')?></td><td><?=e($row['hsn_sac']?:'—')?></td><td><?=e($row['category']?:'—')?></td><td><?=e($row['unit'])?></td><td><?=money($row['price'])?></td><td><?=e($row['tax_rate'])?>%</td><td><form method="post" onsubmit="return confirm('Archive this item?')"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="link-button">Archive</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="9" class="empty-row">Add catalog items with their assigned HSN/SAC and tax rate before issuing GST invoices.</td></tr><?php endif?></tbody></table></div></div>
<?php modal_form('Add catalog item','create',$fields); page_end();
